  prefix: {
    type: "text-content",
    default: "Looking for",
    description: "Fixed text",
  },
  text: {
    type: "text-content",
    default: "leads | customers | subscribers | appointments | demos | quotes | registrants | trials | conversions",
    description: "Words separated by |",
  },
  suffix: {
    type: "text-content",
    default: "?",
    description: "Word suffix",
  },
  fontSize: {
    type: "number",
    default: 60,
    min: 16,
    max: 160,
    step: 1,
    description: "Font size",
    hiddenFromList: false,
  },
  interval: {
    type: "number",
    default: 12,
    min: 6,
    max: 60,
    step: 1,
    description: "Initial frames per word",
    hiddenFromList: false,
  },
  acceleration: {
    type: "number",
