  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["prefix","text","suffix","fontSize","interval","acceleration","transitionFrames","color","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  prefix: "Looking for",
  text: "leads | customers | subscribers | appointments | demos | quotes | registrants | trials | conversions",
  suffix: "?",
  fontSize: 60,
  interval: 12,
  acceleration: 0.9,
  transitionFrames: 6,
  color: "#f5f5f5",
  speed: 1,
};

type InlineWordRollElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof InlineWordRollBase>;

const InlineWordRollInner = forwardRef<
  HTMLDivElement,
  InlineWordRollElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<InlineWordRoll>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <InlineWordRollBase
          {...(componentProps as unknown as ComponentProps<typeof InlineWordRollBase>)}
        />
      </div>
    </Sequence>
  );
});

export const InlineWordRoll = Interactive.withSchema({
  Component: InlineWordRollInner,
  componentName: "<InlineWordRoll>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
